import * as M from './model.js';
export const PROMISES=[
 {id:'books',icon:'book-open',title:'누구나 빌리는 학급문고',pitch:'읽고 싶은 책을 제안하고 서로 차례를 지켜 빌려요.',question:'같은 책을 동시에 읽고 싶으면 어떻게 할까요?',answer:'예약 순서를 적고 기다리는 동안 읽을 책도 함께 소개하겠습니다.',steps:['학생들이 원하는 책과 대출 약속을 모으기','빌림표를 함께 사용하고 불편한 점 돌아보기']},
 {id:'voice',icon:'messages-square',title:'작은 목소리도 들리는 회의',pitch:'말하기 전에 생각을 적고, 말·그림 중 편한 방법으로 제안해요.',question:'발표가 어려운 친구의 의견은 어떻게 들을까요?',answer:'그림과 쪽지를 받을 수 있는 제안함을 함께 만들겠습니다.',steps:['말·글·그림으로 우리 반 제안 모으기','제안을 차례로 읽고 함께 할 일 한 가지 정하기']},
 {id:'play',icon:'dribbble',title:'함께 정하는 쉬는 시간 놀이',pitch:'익숙한 놀이와 새로운 놀이를 번갈아 해 보고 규칙을 같이 정해요.',question:'놀이에 바로 참여하기 어려운 친구는 어떻게 할까요?',answer:'먼저 구경하거나 다른 역할을 고른 뒤 편할 때 참여할 수 있게 하겠습니다.',steps:['해 보고 싶은 놀이와 필요한 도움 확인','정한 규칙으로 짧게 놀고 바꿀 점 이야기하기']},
 {id:'roles',icon:'hand-helping',title:'서로 도와 완성하는 1인 1역',pitch:'한 사람이 힘들 때 도움을 부탁하고 역할을 바꿔 볼 기회를 만들어요.',question:'인기 있는 역할만 고르면 어떻게 할까요?',answer:'희망을 먼저 듣고 차례를 정해 여러 역할을 경험하게 하겠습니다.',steps:['역할의 실제 어려움과 학생 희망 듣기','역할표를 살펴 교환·도움 방법을 함께 정하기']}
];
export const data=state=>state.civics??={election:null,proposals:[]};
const hash=text=>{let n=2166136261;for(const c of String(text))n=Math.imul(n^c.codePointAt(0),16777619);return n>>>0;};
const participants=state=>M.remainingStudents(state);
function timeError(state,minutes){const slot=M.currentSlot(state);if(state.room!=='classroom'||state.classLocation!=='classroom'||M.movementBusy(state))return '우리 교실에서 함께 진행해 주세요.';if(!['morning','break','afternoon'].includes(slot.kind)&&!(slot.kind==='lesson'&&slot.subject==='창체'))return '아침활동·쉬는 시간·수업 후 또는 창체 시간에 진행해 주세요.';if(state.minute+minutes>slot.end)return '다음 수업을 지킬 수 있도록 시간이 더 넉넉할 때 이어서 진행해 주세요.';if(!participants(state).length)return '함께 참여할 학생이 등교한 뒤 진행해 주세요.';if(participants(state).length<state.students.filter(s=>M.isPresent(state,s.id)).length)return '이미 하교한 학생이 있어요. 모두 함께 있는 아침활동·쉬는 시간·창체 시간에 이어서 진행해 주세요.';return null;}
function spend(state,minutes,text){M.advance(state,minutes);M.log(state,text);}
export function announce(state){if(data(state).election)return {error:'이번 학기 선거 기록이 이미 있습니다.'};const error=timeError(state,2);if(error)return {error};const volunteers=participants(state).filter(s=>hash(state.config.seed+'volunteer'+s.id)%5!==0).sort((a,b)=>hash('candidate'+state.config.seed+a.id)-hash('candidate'+state.config.seed+b.id)).slice(0,Math.min(4,state.students.length));data(state).election={id:'election-1',stage:'candidates',date:M.stamp(state),day:state.day,candidates:volunteers.map((s,i)=>({id:s.id,promise:PROMISES[i%4].id,active:true,qa:false})),campaign:null,result:null,pledges:[]};spend(state,2,'학급선거 공고와 학생 출마 희망 확인');return {ok:true};}
export function withdraw(state,id){const e=data(state).election,c=e?.candidates.find(c=>c.id===id);if(!c||e.stage!=='candidates'||!c.active)return false;c.active=false;M.log(state,state.students.find(s=>s.id===id).name+' · 출마 희망 변경 확인');return true;}
export function prepare(state){const e=data(state).election;if(e?.stage!=='candidates')return {error:'후보 희망을 먼저 확인해 주세요.'};const error=timeError(state,3);if(error)return {error};if(!e.candidates.some(c=>c.active)){e.stage='result';e.result={voters:0,counts:[],abstain:0,winners:[],round:0,method:'무후보 · 공동 자치',date:M.stamp(state)};e.pledges=[{id:'class-voice',ownerIds:[],promise:'voice',steps:[false,false]}];spend(state,3,'후보가 없어 학급 공동 제안 활동으로 결정');return {ok:true};}e.stage='campaign';spend(state,3,'모든 후보에게 같은 발표 시간과 준비 기회 안내');return {ok:true};}
export function askCandidate(state,id){const e=data(state).election,c=e?.candidates.find(c=>c.id===id);if(e?.stage!=='campaign'||!c?.active||c.qa)return false;c.qa=true;return PROMISES.find(p=>p.id===c.promise);}
export function campaign(state,format){const e=data(state).election;if(e?.stage!=='campaign'||!['poster','speech'].includes(format))return {error:'후보 발표 단계를 확인해 주세요.'};const error=timeError(state,5);if(error)return {error};e.campaign={format,date:M.stamp(state),equalMinutes:true};e.stage='vote';spend(state,5,format==='poster'?'모든 후보의 공약 게시·질문 시간 운영':'모든 후보에게 같은 시간으로 공약 발표 기회 제공');return {ok:true};}
export function vote(state){const e=data(state).election;if(e?.stage!=='vote')return {error:'공약 발표 뒤에 투표할 수 있어요.'};const error=timeError(state,5);if(error)return {error};const candidates=e.candidates.filter(c=>c.active),voters=participants(state);if(!candidates.length)return {error:'등록된 후보를 확인해 주세요.'};const counts=Object.fromEntries(candidates.map(c=>[c.id,0]));let abstain=0;
 // Preferences use fictional pupil interests and promises; gender, appearance,
 // family circumstances, scores and teacher relations never enter voting.
 for(const voter of voters){const n=hash(state.config.seed+'ballot'+voter.id);if(n%17===0){abstain++;continue;}if(candidates.length===1){if(n%5===0){abstain++;continue;}counts[candidates[0].id]++;continue;}const ranked=candidates.map(c=>({id:c.id,value:hash(state.config.seed+voter.id+c.promise)})).sort((a,b)=>b.value-a.value);counts[ranked[0].id]++;}
 const high=Math.max(...Object.values(counts)),tied=candidates.filter(c=>counts[c.id]===high).map(c=>c.id);let winners=candidates.length===1?(high>voters.length/2?tied:[]):high>0?tied:[];const method=high===0?'유효표 없음 · 공동 자치':candidates.length===1?'단독 후보 찬반 확인':tied.length>1?'동점 · 공동대표':'비밀투표';e.result={voters:voters.length,counts:candidates.map(c=>({id:c.id,votes:counts[c.id]})),abstain,winners,round:1,method,date:M.stamp(state)};e.stage='result';const chosen=winners.length?candidates.filter(c=>winners.includes(c.id)):[{id:null,promise:'voice'}];e.pledges=chosen.map((c,i)=>({id:'pledge-'+i,ownerIds:c.id?[c.id]:[],promise:c.promise,steps:[false,false]}));for(const s of state.students)if(winners.includes(s.id))s.civicOffice='학급대표';for(const student of voters)M.remember(state,student,'후보들의 공약을 듣고 자신의 의견으로 학급선거에 참여했다.',1);spend(state,5,'학급선거 결과 확정 · '+(winners.length?winners.map(id=>state.students.find(s=>s.id===id).name).join('·'):'공동 자치'));M.addNote(state,'teacher','학급선거 · '+method+' · 투표 참여 '+voters.length+'명. 공약을 학급 자치 활동으로 이어가기로 함.');return {ok:true};}
export function enact(state,id){const e=data(state).election,p=e?.pledges.find(p=>p.id===id);if(!p||e.stage!=='result')return {error:'선거 결과와 공약을 먼저 확인해 주세요.'};const index=p.steps.findIndex(done=>!done);if(index<0)return {error:'이 공약의 두 활동을 이미 마쳤습니다.'};const error=timeError(state,5);if(error)return {error};p.steps[index]=true;p.updated=M.stamp(state);const text=PROMISES.find(x=>x.id===p.promise).steps[index];for(const student of participants(state))M.remember(state,student,'학급 자치 · '+text,1);state.unity=M.clamp(state.unity+2);spend(state,5,'공약 실천 · '+text);M.addNote(state,'teacher','학급 자치 활동: '+text);return {ok:true};}
